export function HireInput({ label, required = false, hint, error, ...props }) {
  return (
    <label className="hire-field">
      <span className="hire-label">{label}{required ? <b aria-hidden="true">*</b> : null}</span>
      <input className={`hire-input${error ? " invalid" : ""}`} {...props} />
      {hint && !error ? <span className="hire-hint">{hint}</span> : null}
      {error ? <span className="hire-error">{error}</span> : null}
    </label>
  );
}

export function HireDropdown({
  value,
  onChange,
  options,
  placeholder = "Select",
  ariaLabel = "Select",
  disabled = false,
  invalid = false,
  compact = false,
  placement = "down",
  align = "left",
  className = "",
  displayLabel = "",
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef(null);
  const triggerRef = useRef(null);
  const normalizedOptions = options.map((option) =>
    typeof option === "string" ? { value: option, label: option } : option
  );
  const selected = normalizedOptions.find((option) => option.value === value);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <span
      ref={rootRef}
      className={[
        "hire-dropdown",
        open ? "open" : "",
        compact ? "compact" : "",
        placement === "up" ? "drop-up" : "",
        align === "right" ? "align-right" : "",
        className,
      ].filter(Boolean).join(" ")}
    >
      <button
        ref={triggerRef}
        type="button"
        className={`hire-dropdown-trigger${invalid ? " invalid" : ""}`}
        aria-label={ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        disabled={disabled}
        onClick={() => setOpen((current) => !current)}
        onKeyDown={(event) => {
          if ((event.key === "ArrowDown" || event.key === "Enter" || event.key === " ") && !open) {
            event.preventDefault();
            setOpen(true);
            requestAnimationFrame(() => rootRef.current?.querySelector('[role="option"]')?.focus());
          }
        }}
      >
        <span className={!selected ? "placeholder" : ""}>{displayLabel || selected?.label || placeholder}</span>
        <svg className="hire-dropdown-chevron" viewBox="0 0 20 20" aria-hidden="true">
          <path d="m5 7.5 5 5 5-5" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>

      {open && !disabled ? (
        <span className="hire-dropdown-menu" role="listbox" aria-label={ariaLabel}>
          {normalizedOptions.map((option) => {
            const active = option.value === value;
            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={active}
                className={active ? "active" : ""}
                onClick={() => {
                  onChange(option.value);
                  setOpen(false);
                  triggerRef.current?.focus();
                }}
                onKeyDown={(event) => {
                  if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
                  event.preventDefault();
                  const buttons = [...rootRef.current.querySelectorAll('[role="option"]')];
                  const current = buttons.indexOf(event.currentTarget);
                  const next = current + (event.key === "ArrowDown" ? 1 : -1);
                  buttons[(next + buttons.length) % buttons.length]?.focus();
                }}
              >
                <span>{option.label}</span>
                {active ? (
                  <svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 10.2 3.1 3.1L15 6.7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                ) : null}
              </button>
            );
          })}
        </span>
      ) : null}
    </span>
  );
}

export function HireSelect({ label, required = false, value, onChange, options, placeholder = "Select", error, disabled = false }) {
  return (
    <div className="hire-field">
      <span className="hire-label">{label}{required ? <b aria-hidden="true">*</b> : null}</span>
      <HireDropdown
        value={value}
        onChange={onChange}
        options={options}
        placeholder={placeholder}
        ariaLabel={label}
        disabled={disabled}
        invalid={Boolean(error)}
      />
      {error ? <span className="hire-error">{error}</span> : null}
    </div>
  );
}

export function HireSegment({ value, onChange, options, ariaLabel }) {
  return (
    <div className="hire-segment" role="group" aria-label={ariaLabel}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className={value === option.value ? "active" : ""}
          aria-pressed={value === option.value}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}


